-- WP-CATALOGO-BASE (DEUDA_LEGAJO DL-141; encargo de consolidación de Dirección del 2026-10-19, bloque 4): la
-- correspondencia del catálogo base de alimentos con su fuente. 5 cortes vacunos con un nombre fiel a la pieza de USDA,
-- 11 nombres alternativos retirados porque nombraban otro ingrediente u otra preparación, y 2 nombres alternativos
-- nuevos. GENERADA por scripts/catalogo-base/generar-migracion.mjs desde prisma/datos/catalogo-base/correcciones.json: no
-- se edita a mano (prisma/datos/catalogo-base/LEEME.md). Las migraciones de los tramos 2 y 3 ya están aplicadas: no se tocan.
-- - Un corte que cambia de nombre es una versión nueva de su alimento, sucesora de la del tramo 3. La composición, la
--   disponibilidad y la fuente externa (con la descripción original de USDA) se copian tal cual de la versión anterior;
--   la procedencia lleva la marca de esta migración y suma la correspondencia con la pieza de USDA (DIRECTA o
--   APROXIMADA), su fundamento y sus fuentes (el glosario de cortes de exportación de la SAGPyA que publica el IPCVA, y
--   las especificaciones IMPS de USDA).
-- - La versión anterior queda: los planes activados y las recetas que la citan conservan su instantánea (REG-06-101,
--   REG-06-112). El buscador muestra la vigente, que es la terminal de la cadena.
-- - Retirar un nombre es un hecho aparte, con su motivo (DL-141 D-2): el nombre queda en la historia.
-- - Cada inserción saltea lo que ya está (UUID v5 en el espacio «be.dl-141.catalogo-base», ON CONFLICT DO NOTHING), y la
--   versión nueva solo se agrega sobre la del tramo 3 si esa sigue siendo la vigente: correrla dos veces no agrega nada.
-- Solo agrega filas: no toca tablas, triggers ni lo ya sembrado (REG-06-112). No es una recomendación (INV-06-143).

-- 1. Los cortes con un nombre fiel: una versión nueva, con la composición y la fuente externa de la anterior.
INSERT INTO "version_de_elemento_nutricional" ("id", "elemento_id", "predecesora_id", "nombre", "composicion", "disponibilidad", "procedencia", "momento_de_registro")
SELECT n."id"::uuid, v."elemento_id", v."id", n."nombre", v."composicion", v."disponibilidad", v."procedencia" || n."agregado"::jsonb,
       '2026-10-19T21:00:00.000Z'::timestamptz
  FROM (VALUES
    ('a0a16c3e-f03b-549a-aaa5-111abed874f3', '155a4a58-6775-548b-a9d3-1d18760e4bb0', 'Cuadril, magro, crudo', 'Cuadril sin colita (top sirloin), magro, crudo', '{"siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","correspondencia":{"tipo":"APROXIMADA","nota":"Es el top sirloin de USDA: el cuadril sin la colita, con la tapa o sin ella (SR Legacy no lo aclara).","pieza":"Top sirloin butt (IMPS 184): M. gluteus medius, M. gluteus accessorius y M. gluteus profundus, con la tapa (M. biceps femoris) o sin ella (IMPS 184A y 184B); sin el bottom sirloin, que lleva la colita (tri-tip)","preparacion":"crudo","grasa":"solo la parte magra separable, de un bife cortado con 1/8\" (3 mm) de grasa externa","fundamento":"El glosario relaciona «Cuadril (o cadera) con Tapa sin Colita» con «Rump / Sirloin Butt / Loin End» y «Corazón de Cuadril» con «Eye of Rump / Rump, Cap and Tail Off». El top sirloin de USDA (IMPS 184) es ese corazón, con la tapa o sin ella, y deja afuera la colita. La descripción de SR Legacy no dice si el bife lleva la tapa: el nombre dice «sin colita» y la correspondencia queda aproximada.","fuentes":[{"cita":"Secretaría de Agricultura, Ganadería, Pesca y Alimentos (SAGPyA): «Glossary of main export cuts from Argentina», con la tabla «Nombres equivalentes o aproximados de cortes de carne bovina en distintos países» (mayo de 2004), publicado por el IPCVA","url":"https://ipcva.agrositio.com/files/glosario.pdf","sha256":"13bebcfb4fee3493a1e869e3c954936327824b9c06c5ed03d7870092ac68509b","consultadoEl":"2026-10-19"},{"cita":"USDA Agricultural Marketing Service: «Institutional Meat Purchase Specifications. Fresh Beef, Series 100»","url":"https://www.ams.usda.gov/sites/default/files/media/IMPS_100_Fresh_Beef%5B1%5D.pdf","sha256":"fe7413bd8e30a3bf58a2d887ca22e4803e723b986f1f0c8c1bae4ae59dbbd569","consultadoEl":"2026-10-19"}]},"correccion":{"nombreAnterior":"Cuadril, magro, crudo"}}'), -- FDC 174055, correspondencia APROXIMADA
    ('aa1e05e9-844a-5dc4-b3fc-b5a24f2eb23f', '4eb40f67-e518-50fc-839c-e393a7d8e340', 'Cuadril, magro, asado', 'Cuadril sin colita (top sirloin), magro, asado', '{"siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","correspondencia":{"tipo":"APROXIMADA","nota":"Es el top sirloin de USDA: el cuadril sin la colita, con la tapa o sin ella (SR Legacy no lo aclara).","pieza":"Top sirloin butt (IMPS 184): M. gluteus medius, M. gluteus accessorius y M. gluteus profundus, con la tapa (M. biceps femoris) o sin ella (IMPS 184A y 184B); sin el bottom sirloin, que lleva la colita (tri-tip)","preparacion":"asado al grill (broiled)","grasa":"solo la parte magra separable, de un bife sin grasa externa (0\"); el crudo es de un bife con 1/8\", y la parte magra cambia poco","fundamento":"La misma pieza que el crudo (IMPS 184), con la misma correspondencia aproximada. SR Legacy publica el asado de la parte magra con 0\" y con 1/8\" de grasa externa; el que está sembrado es el de 0\".","fuentes":[{"cita":"Secretaría de Agricultura, Ganadería, Pesca y Alimentos (SAGPyA): «Glossary of main export cuts from Argentina», con la tabla «Nombres equivalentes o aproximados de cortes de carne bovina en distintos países» (mayo de 2004), publicado por el IPCVA","url":"https://ipcva.agrositio.com/files/glosario.pdf","sha256":"13bebcfb4fee3493a1e869e3c954936327824b9c06c5ed03d7870092ac68509b","consultadoEl":"2026-10-19"},{"cita":"USDA Agricultural Marketing Service: «Institutional Meat Purchase Specifications. Fresh Beef, Series 100»","url":"https://www.ams.usda.gov/sites/default/files/media/IMPS_100_Fresh_Beef%5B1%5D.pdf","sha256":"fe7413bd8e30a3bf58a2d887ca22e4803e723b986f1f0c8c1bae4ae59dbbd569","consultadoEl":"2026-10-19"}]},"correccion":{"nombreAnterior":"Cuadril, magro, asado"}}'), -- FDC 168634, correspondencia APROXIMADA
    ('7367ee33-e94f-5c00-8f0a-f2a966a19330', 'd5a54ba6-f1b4-55e2-9ad9-fbf9cd3205d4', 'Entraña, magra, asada', 'Entraña fina, magra, asada', '{"siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","correspondencia":{"tipo":"DIRECTA","nota":null,"pieza":"Outside skirt (IMPS 121C y 1121E): el diafragma, sin el centro de la entraña (hanging tender) y sin el inside skirt (M. transversus abdominis, IMPS 121D)","preparacion":"asada al grill (broiled)","grasa":"solo la parte magra separable, sin grasa externa (0\")","fundamento":"El glosario relaciona «Entraña Fina / Diafragma» con «Thin Skirt / Outside Skirt / Diaphragm», y la «Entraña Gruesa o Centro de Entraña» con otra pieza («Hanging Tender / Thick Skirt»). El outside skirt de USDA es el diafragma (IMPS 121C). SR Legacy no publica la entraña cruda.","fuentes":[{"cita":"Secretaría de Agricultura, Ganadería, Pesca y Alimentos (SAGPyA): «Glossary of main export cuts from Argentina», con la tabla «Nombres equivalentes o aproximados de cortes de carne bovina en distintos países» (mayo de 2004), publicado por el IPCVA","url":"https://ipcva.agrositio.com/files/glosario.pdf","sha256":"13bebcfb4fee3493a1e869e3c954936327824b9c06c5ed03d7870092ac68509b","consultadoEl":"2026-10-19"},{"cita":"USDA Agricultural Marketing Service: «Institutional Meat Purchase Specifications. Fresh Beef, Series 100»","url":"https://www.ams.usda.gov/sites/default/files/media/IMPS_100_Fresh_Beef%5B1%5D.pdf","sha256":"fe7413bd8e30a3bf58a2d887ca22e4803e723b986f1f0c8c1bae4ae59dbbd569","consultadoEl":"2026-10-19"}]},"correccion":{"nombreAnterior":"Entraña, magra, asada"}}'), -- FDC 168745, correspondencia DIRECTA
    ('74b2fe0a-341c-5fa2-bf87-013bbd63e168', 'b577ec45-175a-574a-ac74-248fb5348a98', 'Vacío, magro y grasa, crudo', 'Bife de vacío, magro y grasa, crudo', '{"siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","correspondencia":{"tipo":"DIRECTA","nota":null,"pieza":"Flank steak (IMPS 193): el M. rectus abdominis, separado del M. transversus abdominis y de los oblicuos interno y externo","preparacion":"crudo","grasa":"la parte magra y la grasa separable, sin grasa externa (0\")","fundamento":"El glosario de cortes de exportación relaciona «Bife de Vacío» con «Flank Steak», y el flank steak de USDA es el M. rectus abdominis (IMPS 193). El vacío entero es otra pieza («Hindquarter / Flank or Thin Flank»): suma el transverso y los oblicuos, y más grasa. SR Legacy no lo publica, así que esta composición no representa al vacío comercial completo.","fuentes":[{"cita":"Secretaría de Agricultura, Ganadería, Pesca y Alimentos (SAGPyA): «Glossary of main export cuts from Argentina», con la tabla «Nombres equivalentes o aproximados de cortes de carne bovina en distintos países» (mayo de 2004), publicado por el IPCVA","url":"https://ipcva.agrositio.com/files/glosario.pdf","sha256":"13bebcfb4fee3493a1e869e3c954936327824b9c06c5ed03d7870092ac68509b","consultadoEl":"2026-10-19"},{"cita":"USDA Agricultural Marketing Service: «Institutional Meat Purchase Specifications. Fresh Beef, Series 100»","url":"https://www.ams.usda.gov/sites/default/files/media/IMPS_100_Fresh_Beef%5B1%5D.pdf","sha256":"fe7413bd8e30a3bf58a2d887ca22e4803e723b986f1f0c8c1bae4ae59dbbd569","consultadoEl":"2026-10-19"}]},"correccion":{"nombreAnterior":"Vacío, magro y grasa, crudo"}}'), -- FDC 169563, correspondencia DIRECTA
    ('b14d18b8-fbfd-5c13-b938-bb1935f3aa2d', '0e1caf8a-7eb0-5320-83ce-042b573b77d0', 'Vacío, magro y grasa, asado', 'Bife de vacío, magro y grasa, asado', '{"siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","correspondencia":{"tipo":"DIRECTA","nota":null,"pieza":"Flank steak (IMPS 193): el M. rectus abdominis, separado del M. transversus abdominis y de los oblicuos interno y externo","preparacion":"asado al grill (broiled)","grasa":"la parte magra y la grasa separable, sin grasa externa (0\")","fundamento":"La misma pieza que el crudo (IMPS 193): el bife de vacío, no el vacío entero.","fuentes":[{"cita":"Secretaría de Agricultura, Ganadería, Pesca y Alimentos (SAGPyA): «Glossary of main export cuts from Argentina», con la tabla «Nombres equivalentes o aproximados de cortes de carne bovina en distintos países» (mayo de 2004), publicado por el IPCVA","url":"https://ipcva.agrositio.com/files/glosario.pdf","sha256":"13bebcfb4fee3493a1e869e3c954936327824b9c06c5ed03d7870092ac68509b","consultadoEl":"2026-10-19"},{"cita":"USDA Agricultural Marketing Service: «Institutional Meat Purchase Specifications. Fresh Beef, Series 100»","url":"https://www.ams.usda.gov/sites/default/files/media/IMPS_100_Fresh_Beef%5B1%5D.pdf","sha256":"fe7413bd8e30a3bf58a2d887ca22e4803e723b986f1f0c8c1bae4ae59dbbd569","consultadoEl":"2026-10-19"}]},"correccion":{"nombreAnterior":"Vacío, magro y grasa, asado"}}') -- FDC 168733, correspondencia DIRECTA
  ) AS n("id", "anterior", "nombre_anterior", "nombre", "agregado")
  JOIN "version_de_elemento_nutricional" v ON v."id" = n."anterior"::uuid AND v."nombre" = n."nombre_anterior"
 WHERE NOT EXISTS (SELECT 1 FROM "version_de_elemento_nutricional" s WHERE s."predecesora_id" = v."id")
ON CONFLICT ("id") DO NOTHING;

-- 2. Los nombres alternativos que nombran otro ingrediente u otra preparación: se retiran, con su motivo.
INSERT INTO "retiro_de_nombre_alternativo_de_alimento" ("nombre_id", "motivo", "profesional_id", "procedencia", "momento_de_registro")
SELECT a."id", n."motivo", NULL, n."procedencia"::jsonb, '2026-10-19T21:00:00.000Z'::timestamptz
  FROM (VALUES
    ('ced929d2-939b-5c88-baa3-52bd957c7380', 'Nombra la avena seca en copos, no la avena cocida: cambia la preparación.', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}'), -- Copos de avena (FDC 173905)
    ('97340fcb-2b6a-514b-994b-bc039c959d88', 'Nombra la avena seca en hojuelas, no la avena cocida: cambia la preparación.', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}'), -- Avena en hojuelas (FDC 173905)
    ('0fa8ff31-d585-5742-9cc5-7b5db0cd84d2', 'El surimi es la pasta de pescado; el kanikama la lleva con almidón y azúcar, y USDA da composiciones distintas para los dos: cambia el ingrediente.', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}'), -- Surimi (FDC 174203)
    ('c2713084-4df7-55a2-aabf-00e31b6cb8e3', 'El tomate triturado es otro producto que el puré de tomate: cambia el ingrediente.', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}'), -- Tomate triturado (FDC 170460)
    ('4902fdef-b27b-5bc9-b45b-b98a78670772', 'En la Argentina el queso rallado suele ser reggianito o sardo, no parmesano: cambia el ingrediente.', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}'), -- Queso rallado (FDC 171247)
    ('7697e32c-7316-55ec-be79-16dbf37d9b03', 'El por salut argentino es otro queso que el port-salut que describe USDA: su composición puede ser otra.', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}'), -- Queso por salut (FDC 170849)
    ('74903240-c85b-5f1c-ac69-4c76ca6f0ef6', 'La cajeta se hace en general con leche de cabra: cambia el ingrediente.', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}'), -- Cajeta (FDC 173461)
    ('78431173-fbc4-5dd7-b777-debf74c61e60', 'Ninguna fuente ata la lechuga criolla a la variedad de hoja verde que describe USDA.', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}'), -- Lechuga criolla (FDC 169249)
    ('8c1bf7d2-115c-5218-87c6-ebc7c221fd46', 'La compota suele llevar azúcar, y este puré es sin azúcar: cambia el ingrediente.', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}'), -- Compota de manzana (FDC 171695)
    ('6e8e9933-be7d-50eb-be76-e4b0c778ee97', 'En España «entrecot» nombra bifes del lomo alto y del lomo bajo; el ojo de bife es el lomo alto sin tapa (glosario de cortes de exportación).', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}'), -- Entrecot (FDC 172143)
    ('893eba78-645b-5694-b9ab-3ff963026a79', 'En España «entrecot» nombra bifes del lomo alto y del lomo bajo; el ojo de bife es el lomo alto sin tapa (glosario de cortes de exportación).', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143)."}') -- Entrecot (FDC 172142)
  ) AS n("nombre_id", "motivo", "procedencia")
  JOIN "nombre_alternativo_de_alimento" a ON a."id" = n."nombre_id"::uuid
ON CONFLICT ("nombre_id") DO NOTHING;

-- 3. Los nombres alternativos nuevos, como los del tramo 3.
INSERT INTO "nombre_alternativo_de_alimento" ("id", "elemento_id", "nombre", "idioma", "region", "origen", "procedencia", "momento_de_registro")
SELECT n."id"::uuid, e."id", n."nombre", n."idioma"::"IdiomaDeNombre", n."region", 'SIEMBRA_DE_BE'::"OrigenDeNombreAlternativo", n."procedencia"::jsonb,
       '2026-10-19T21:00:00.000Z'::timestamptz
  FROM (VALUES
    ('c96fd1b9-87cd-5d88-9ade-2b62863e839f', '655cce5c-3b18-5474-974d-93bf6bf7a8ee', 'Lomo alto sin tapa', 'ES', 'ES', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143).","fundamento":"Glosario de cortes de exportación: «Bife Ancho sin Tapa» = «Lomo Alto sin tapa» (España) = «Rib Eye Steak / Rib Eye Roll»."}'), -- Lomo alto sin tapa (FDC 172143)
    ('670652eb-03be-55fa-ba2a-609cf887de6a', '2a2fa558-db67-5629-996d-3add9fa5fdb6', 'Lomo alto sin tapa', 'ES', 'ES', '{"fuente":"catalogo-base","siembra":"WP-CATALOGO-BASE · DL-141 · correspondencia de cortes","nota":"Nombre alternativo curado por BE para el catálogo base: no es una recomendación ni una prescripción (INV-06-143).","fundamento":"Glosario de cortes de exportación: «Bife Ancho sin Tapa» = «Lomo Alto sin tapa» (España) = «Rib Eye Steak / Rib Eye Roll»."}') -- Lomo alto sin tapa (FDC 172142)
  ) AS n("id", "elemento_id", "nombre", "idioma", "region", "procedencia")
  JOIN "elemento_de_catalogo_nutricional" e ON e."id" = n."elemento_id"::uuid
ON CONFLICT ("id") DO NOTHING;
